export function displayStyleLabel(value: string): string {
  if (!value) return "";
  const hit = styleLabelEn[value] || styleLabelEn[value.toLowerCase()];
  if (hit) return hit;
  // Strip residual CJK (incl. fullwidth punctuation) so Chinese is never rendered.
  return value.replace(/[\u4e00-\u9fff\u3000-\u303f\uff01-\uff5e]+/g, " ").replace(/\s+/g, " ").trim();
}
